<template>
<div class="app-review sf-ui" :class="{'customer-mode':!reviewMode,'review-layout':reviewMode}">
  <aside v-if="reviewMode" class="review-rail review-module-nav" aria-label="模块导航">
    <div class="review-brand"><b>SunnyFit<span>.</span></b><span>前端原型</span></div>
    <nav class="review-pages"><section v-for="group in reviewGroups" :key="group.label"><h2>{{ group.label }}</h2><button v-for="item in group.pages" :key="item[0]" type="button" :class="{selected:screen===item[0]}" :aria-current="screen===item[0]?'page':null" @click="selectReviewPage(item[0])">{{ item[1] }}</button></section></nav>
    <router-link class="review-back" to="/commercialization/overview">← 后台原型</router-link>
  </aside>
  <main v-fit-preview class="phone-stage"><div v-copy-block="'page.'+screen" class="phone-frame" :class="{'account-frame':['profile','membership','plans','billing','wallet'].includes(screen)||isProfileSecondary,'membership-frame':screen==='membership','content-detail-frame':['course','program','world-tour-detail'].includes(screen),'tour-browse-frame':screen==='world-tour','profile-frame':screen==='profile','challenge-frame':screen==='challenge','coach-frame':screen==='coach','home-frame':screen==='home','movement-frame':['movement-detail','movement-training'].includes(screen),'movement-landscape':screen==='movement-training'&&movementView.landscape,'native-frame':['home','workout','course','plan','program','history','world-tour','world-tour-detail','result'].includes(screen)}" :aria-busy="loading?'true':'false'" :style="{'--canvas-height':canvasHeight+'px'}">
    <div v-if="loading&&!data" class="mobile-loading">Loading…</div><div v-if="error&&!data" class="mobile-error" role="alert">{{ error }}<button @click="load">Retry</button></div>
    <template v-else-if="data">
      <div v-if="mvpPageFeedback" class="mvp-native-viewport"><mvp-page-feedback :title="screenTitle" :state="mvpPageState" @action="handleAction"/></div><div v-else-if="screen==='result'" class="mvp-native-viewport"><v3-workout-result :key="resultFeedbackKey" :workout="resultWorkout" :review-stage="resultStage" @stage-change="setResultStage" :rpe="resultRpe" :has-insight="resultHasInsight" :body="resultAnalysisBody" :loading="mvpInsightState==='insight-loading'||busy" :review-panel="$route.query.reviewResultPanel" @submit-rpe="submitResultRpe" @panel-change="setResultPanel" @action="handleAction"/></div><div v-else-if="isSourceScreen" ref="sourceViewport" class="source-viewport" :class="'viewport-'+screen"><source-canvas :screen="screen" :user="data.user" :report="presentationData.weeklyReport" :ai-state="mvpAiState" :input-locked="mvpInputLocked" :mvp-member="(isMvpPreview||data.policyVersion===20261014)?mvpMember:null" :can-send-chat="canSendMvpChat" :mvp-state="mvpPageState" :insight-state="mvpInsightState" :plan-state="mvpPlanState" :dynamic-plan="currentDynamicPlan" :draft-plan="dynamicPlanDraft" :active-plan="dynamicPlanActive" :reply-state="mvpReplyState" :name="data.user.name" :message="message" :messages="sessionResults.filter(s=>s.type==='conversation')" :insight-body="mvpInsightBody" :opened-asset="openedConversation" :context="coachContext" :balance="data.wallet.available" :commercial="commercial" :sample-conversation="sampleConversation" :has-insight="mvpHasInsight" :analysis-credits="serviceCost('deep_analysis')" :chat-credits="serviceCost('ai_chat')" :tier="displayContent.tier" :content="displayContent" :courses="courseContents" :workout="programWorkout" :next-workout="nextProgramWorkout" :charge-label="costLabel('deep_analysis')" :chat-label="mvpChatLabel" :program-panel="$route.query.reviewProgramPanel" :start-label="contentStartAction(displayContent).label" :redemption-credits="displayContent.redemptionCredits||0" @input="setMessage" @generate-plan="generateChatPlan" @action="handleAction"/></div>
      <div v-else-if="screen==='weekly'" class="mvp-native-viewport"><v3-weekly-report :report="presentationData.weeklyReport" :user="data.user" :busy="busy" @action="handleAction"/></div>
      <div v-else-if="screen==='challenge'" class="mvp-native-viewport"><v3-challenge :contents="challengeContents" :user="data.user" :busy="busy" @action="handleAction"/></div>
      <div v-else-if="['movement-detail','movement-training'].includes(screen)" class="mvp-native-viewport"><movement-experience v-if="movementContent" ref="movement" :key="userId+movementContent.id+screen+(reviewMode?'review':'preview')" :initial-stage="screen==='movement-detail'?'detail':'prepare'" :content="movementContent" :busy="busy" :review="reviewMode" :review-options="movementReview" @start="authorizeMovement" @prepare="go('movement-training')" @exit="go(screen==='movement-detail'?'movement':'movement-detail')" @complete="go('movement')" @view-state="handleMovementView" @review-live="movementReview={...movementReview,pinned:false}"/></div>
      <div v-else-if="screen==='world-tour'" class="mvp-native-viewport"><v3-world-tour :contents="collectionContents" :user="data.user" @action="handleAction"/></div>
      <div v-else-if="screen==='world-tour-detail'&&selectedWorldTour" class="mvp-native-viewport"><v3-course :content="selectedWorldTour" :user="data.user" :access-label="selectedWorldTour.tier==='premium'?'Premium':'Free'" :start-label="contentStartAction(selectedWorldTour).label" @action="handleAction($event.startsWith('start-course:')?$event.replace('start-course:','start-content:'):$event)"/></div>
      <div v-else-if="screen==='movement'" class="mvp-native-viewport"><v3-content-collection :kind="screen==='movement'?'movement':'world_tour'" :contents="collectionContents" :busy="busy" @action="handleAction"/></div>
      <div v-else-if="screen==='history'" class="history-screen history-screen--native"><sf-page-layout title="Coach history" @back="go('coach')"><sf-menu-row v-for="asset in conversations" :key="asset.id" :label="asset.title" :description="shortDate(asset.createdAt)" @click="readConversation(asset)"/><sf-feedback v-if="!conversations.length" tone="empty" title="No conversations yet" description="Your saved conversations will appear here." action="Open AI Coach" @action="go('coach')"/></sf-page-layout></div>
      <template v-else><header class="app-account-top sf-top-bar-mask"><div class="source-status"><b>9:41</b></div><sf-header v-if="screen!=='profile'" class="mobile-header" :title="screenTitle" glass @back="back"/></header><div ref="accountScroll" class="mobile-scroll"><personal-center v-if="screen==='profile'" :data="data" @go="go" @retry="load"/><profile-secondary v-else-if="isProfileSecondary" :key="data.user.id+':'+screen+':'+($route.query.profileSection||'')+':'+($route.query.profileItem||'')" :screen="screen" :section="$route.query.profileSection" :item="$route.query.profileItem" :parent="$route.query.profileParent" :data="data" @go="go" @retry="load"/><membership-usage v-else-if="screen==='membership'" :data="data" :locale="locale" :busy="busy" @go="go" @restore="restoreMvpPurchases" @retry="load" @subscribe="mvpUpgrade('membership',null,{view:$event})"/><consumer-screens v-else :data="data" :screen="screen" :credit-type="$route.query.creditType" :locale="locale" :busy="busy" @checkout="checkout" @renew="renew" @restore="restore" @ledger="showLedger=true"/><button v-if="returnTo" class="mobile-primary" @click="returnToFlow">Return to {{ returnTitle }}</button></div></template>
      <div v-if="error" class="source-error" role="alert">{{ error }}<button @click="error=''" aria-label="Dismiss error">×</button></div>
      <div v-if="sourceGap&&!reviewMode" class="source-section-feedback"><sf-toast :open="!!sourceGap" message="This section isn't available in this preview yet." @input="sourceGap=''"/></div>
      <mvp-upgrade-sheet :gate="mvpDisplayGate" :credit-offers="mvpCreditOffers" :member="mvpMember" :wall="mvpWall" @close="cancelMvpPurchase('dismiss',$event)" @select="selectWallOffer" @view="changeWallView" @benefit="changeWallBenefit" @restore="restoreWallPurchases" @reload="reloadWallOffers" @purchase="purchaseMvpOffer" @resume="resumeMvpPurchase" @retry="retryMvpPurchase" @check="checkMvpPurchase" @usage="viewMvpUsage" @refresh="refreshMvpAllowance"/><commerce-sheets :app="sheetContext" @close="closeSheet" @resolve="resolveGate" @purchase="confirmPurchase" @service="runService" @redeem="confirmRedemption" @renew="applyRenewal" @done="finishNotice" @workout="openProgramWorkout"/>
      <sf-toast :open="!!appToast" :message="appToast" @input="appToast=''"/>
      <button v-if="mvpPendingPurchase&&!mvpGate" type="button" class="mvp-purchase-pending" @click="mvpGate=mvpPendingPurchase">Purchase confirmation pending · Check status</button>
    </template>
  </div><p v-if="reviewMode" class="phone-caption">{{ screenTitle }} · Demo 评审</p></main>
  <review-document v-if="reviewMode" :screen="screen" :model="reviewDocument" :source="note.url" @page-state="applyReviewState('page',$event)" @component-state="applyReviewState($event.id,$event.value)" @action="reviewDocumentAction" @preview="openReviewPreview"/>
  <copy-context-menu v-if="reviewMode" :context="collaborationContext"/>
</div>
</template>
<script>
import controller from './controller'
import MvpPageFeedback from './MvpPageFeedback'
import MvpUpgradeSheet from './ContextualSubscription'
import ReviewDocument from './review/ReviewDocument'
import CopyContextMenu from './review/CopyContextMenu'
import {closeCopyBlock,copyState} from '@/copy/operations-copy'
import fitPreview from '@/demo/fit-preview'
import CommerceSheets from './CommerceSheets'
import {SfHeader,SfToast,SfPageLayout,SfMenuRow,SfFeedback} from '@/design-system'
export default {...controller,beforeRouteUpdate(to,from,next){if(copyState.busy)return next(false);next(closeCopyBlock()?undefined:false)},beforeRouteLeave(to,from,next){if(copyState.busy)return next(false);next(closeCopyBlock()?undefined:false)},directives:{fitPreview},components:{...controller.components,MvpPageFeedback,MvpUpgradeSheet,ReviewDocument,CopyContextMenu,CommerceSheets,SfHeader,SfToast,SfPageLayout,SfMenuRow,SfFeedback},computed:{...controller.computed,collaborationContext(){const state=this.reviewDocument.states.find(state=>state.value===this.reviewDocument.active||state.id===this.reviewDocument.active);return {page:this.screenTitle,state:[state?state.label:this.reviewDocument.active,...this.reviewDocument.sections.filter(section=>section.states&&section.states.length>1).map(section=>{const active=section.states.find(item=>item.value===section.active||item.id===section.active);return active?section.title+'：'+active.label:''})].filter(Boolean).join(' · '),path:this.$route.path}},sheetContext(){return {...this.$data,displayContent:this.displayContent,returnTo:this.returnTo,returnTitle:this.returnTitle,money:this.money,shortDate:this.shortDate,serviceLabel:this.serviceLabel,cadenceLabel:this.cadenceLabel,eventLabel:this.eventLabel}}}}
</script>
<style scoped>.mvp-native-viewport{height:100%;position:relative;min-width:0;overflow:hidden}</style>
